import { test, expect } from '@playwright/test';

test.describe('Full Checkout Flow - Standard User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
  });

  test('should successfully complete a full checkout with standard user credentials', async ({ page }) => {
    // Login with standard user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Add backpack to cart
    const backpackItem = page.getByTestId('add-to-cart-sauce-labs-backpack');
    await backpackItem.click();

    // Navigate to cart
    const cartLink = page.getByRole('link', { name: 'Shopping Cart' });
    await cartLink.click();

    // Proceed to checkout
    const checkoutButton = page.getByTestId('checkout');
    await checkoutButton.click();

    // Fill in checkout information
    const firstNameInput = page.getByTestId('firstName');
    const lastNameInput = page.getByTestId('lastName');
    const postalCodeInput = page.getByTestId('postalCode');
    const continueButton = page.getByTestId('continue');

    await firstNameInput.fill('Saif');
    await lastNameInput.fill('Afzal');
    await postalCodeInput.fill('20001');
    await continueButton.click();

    // Verify overview page and item total
    const itemTotal = page.getByText('$29.99');
    await expect(itemTotal).toBeVisible();

    // Complete checkout
    const finishButton = page.getByTestId('finish');
    await finishButton.click();

    // Verify confirmation message
    const confirmationHeader = page.getByRole('heading', { name: 'Thank you for your order!' });
    await expect(confirmationHeader).toBeVisible();
  });

  test('should handle checkout with invalid postal code and prevent order completion', async ({ page }) => {
    // Login with standard user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Add backpack to cart
    const backpackItem = page.getByTestId('add-to-to-cart-sauce-labs-backpack');
    await backpackItem.click();

    // Navigate to cart
    const cartLink = page.getByRole('link', { name: 'Shopping Cart' });
    await cartLink.click();

    // Proceed to checkout
    const checkoutButton = page.getByTestId('checkout');
    await checkoutButton.click();

    // Fill in checkout information with invalid postal code
    const firstNameInput = page.getByTestId('firstName');
    const lastNameInput = page.getByTestId('lastName');
    const postalCodeInput = page.getByTestId('postalCode');
    const continueButton = page.getByTestId('continue');

    await firstNameInput.fill('Saif');
    await lastNameInput.fill('Afzal');
    await postalCodeInput.fill('invalid-zip');
    await continueButton.click();

    // Verify error message for invalid postal code
    const postalCodeError = page.getByText('Please enter a valid postal code');
    await expect(postalCodeError).toBeVisible();

    // Verify order was not completed
    const confirmationHeader = page.getByRole('heading', { name: 'Thank you for your order!' });
    await expect(confirmationHeader).not.toBeVisible();
  });
});
